-- Censo Demografico 2022: escolaridade da populacao municipal de 18 anos ou mais.

-- Reproduzivel: https://cdn.tse.jus.br/estatistica/sead/odsele/municipio_tse_ibge/municipio_tse_ibge.zip
-- IBGE SIDRA: https://sidra.ibge.gov.br/tabela/10061 (API: tabela 10061, variavel 2667, periodo 2022).
-- Categorias de instrucao: 9493, 9494, 9495 e 99713; grupo etario total 95253; sexo total 6794; cor/raca total 95251.

-- Escopo: AC, AL, BA, DF, RO e SP. Faixas mutuamente exclusivas; percentual = faixa / total 18+ do municipio.

-- Soma das faixas fica 32 abaixo do total no agregado; 510 municipios têm diferenca de ate 2 pessoas. Valores fonte preservados, sem redistribuicao.

BEGIN TRANSACTION;

CREATE TABLE IF NOT EXISTS public.fato_escolaridade_populacao (cd_municipio_ibge VARCHAR NOT NULL, ano_referencia SMALLINT NOT NULL, ds_faixa_etaria VARCHAR(40) NOT NULL, ds_nivel_instrucao VARCHAR NOT NULL, qt_pessoas BIGINT NOT NULL, qt_populacao BIGINT NOT NULL, pct_populacao DECIMAL(7,4), PRIMARY KEY (cd_municipio_ibge, ano_referencia, ds_faixa_etaria, ds_nivel_instrucao));

UPDATE public.municipio AS m SET cd_municipio_ibge = x.cd_ibge FROM (VALUES

